const statusLabels={en:{Lead:'Lead','In progress':'In progress',Completed:'Completed'},fr:{Lead:'Prospect','In progress':'En cours',Completed:'Terminé'},pt:{Lead:'Potencial','In progress:' : 'Em andamento','In progress':'Em andamento',Completed:'Concluído'},es:{Lead:'Contacto','In progress':'En curso',Completed:'Completado'},ar:{Lead:'عميل محتمل','In progress':'قيد التنفيذ',Completed:'مكتمل'}};
let lang=(function(){try{return localStorage.getItem('tampslat-language')||'en'}catch(e){return 'en'}})(),activeTool='proposal',activeView='home',recent=[],clients=[],brand={name:'',owner:'',email:'',phone:'',website:'',currency:'NGN',color:'#7258e8'},selectedColor='#7258e8';
const currencyMeta={NGN:{symbol:'₦',locale:'en-NG'},USD:{symbol:'$',locale:'en-US'},GBP:{symbol:'£',locale:'en-GB'},EUR:{symbol:'€',locale:'de-DE'}};
function tr(k){return (translations[lang]&&translations[lang][k])||translations.en[k]||k}function money(v,c){c=c||workspaceCurrency;let m=currencyMeta[c]||({USD:{symbol:'$',locale:'en-US'},EUR:{symbol:'€',locale:'de-DE'},GBP:{symbol:'£',locale:'en-GB'},CAD:{symbol:'CA$',locale:'en-CA'}}[c])||currencyMeta.NGN; v=Number(v||0)*(currencyRates[c]||1); try{return m.symbol+Number(v||0).toLocaleString(m.locale,{maximumFractionDigits:2})}catch{return m.symbol+Number(v||0).toLocaleString()}}
function toast(msg){let el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2600)}
function applyLanguage(){try{localStorage.setItem('tampslat-language',lang)}catch(e){};document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';$$('[data-i18n]').forEach(el=>{let k=el.dataset.i18n;if(translations[lang][k])el.innerHTML=translations[lang][k]});$$('[data-i18n-placeholder]').forEach(el=>{el.placeholder=tr(el.dataset.i18nPlaceholder)});$('#language').value=lang;renderClients();renderRecent();updateEstimate();}
function showView(view){activeView=view;$$('.view').forEach(v=>v.classList.toggle('active',v.id==='view-'+view));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('.sidebar').classList.remove('mobile-open');window.scrollTo({top:0,behavior:'smooth'});if(view==='clients')renderClients();if(view==='brand')syncBrandPreview()}
function openTool(tool){activeTool=tool;if(tool==='calculator'){showView('calculator');return}if(tool==='brand'){showView('brand');return}if(tool==='clients'){showView('clients');return}showView('editor');const config={proposal:{title:'Project Proposal',heading:'Proposal builder',overview:'Describe the client’s need and your approach. Use this space to explain the value you will deliver.',scope:'Discovery and planning\nCore service delivery\nReview and handover',terms:'50% deposit to begin; 50% on approval of final delivery.',next:'Reply to confirm the scope and preferred start date.'},quotation:{title:'Quotation / Invoice',heading:'Quotation & invoice',overview:'Thank you for the opportunity to provide this quotation. The proposed work and fees are outlined below.',scope:'Service / deliverable — 1\nAdditional work — as agreed',terms:'Quotation valid for 14 days. Work begins after written approval and the agreed deposit.',next:'Approve this quotation in writing to confirm the booking.'},brief:{title:'Client Discovery Brief',heading:'Client brief',overview:'This brief captures the goals, audience and requirements for our work together.',scope:'Business goals and desired outcome\nTarget audience and key message\nDeliverables, constraints and success measures',terms:'Information supplied will be used to scope and deliver the agreed service.',next:'Please review the brief and share any missing information before kickoff.'},completion:{title:'Project Completion Report',heading:'Project completion report',overview:'This report summarises the work completed, the deliverables supplied and any recommendations for the next phase.',scope:'Deliverables completed\nFiles and access handed over\nOutstanding items / recommendations',terms:'Any additional work will be agreed and quoted separately.',next:'Please review the delivery and share feedback within the agreed review period.'},email:{title:'Client Follow-up Email',heading:'Client email scripts',overview:'Hello [Client Name],\n\nI hope you are doing well. I’m following up on the proposal / conversation below and would be happy to clarify any details or adjust the scope to suit your priorities.',scope:'Proposed next step: confirm your preferred option\nSuggested action: book a short call or reply with questions',terms:'The scope, fee and timeline will be confirmed in writing before work begins.',next:'Thank you for your time. I look forward to hearing from you.'}};let c=config[tool]||config.proposal;$('#editorHeading').textContent=tr(tool==='proposal'?'proposal':tool==='quotation'?'quotation':tool==='brief'?'brief':tool==='completion'?'completion':'emailtemplates');$('#docTitle').value=c.title;$('#docClient').value='';$('#docPrepared').value=brand.name||brand.owner||'';$('#docOverview').value=c.overview;$('#docScope').value=c.scope;$('#docTimeline').value=tool==='brief'?'Before kickoff':'2 weeks';$('#docDue').value='';$('#docAmount').value=tool==='quotation'?'0':'';$('#docCurrency').value=brand.currency||'NGN';$('#docTerms').value=c.terms;$('#docNext').value=c.next;updateDocumentPreview();}
function docData(){return {kind:activeTool,title:$('#docTitle').value||'Untitled document',client:$('#docClient').value||'Client or company name',prepared:$('#docPrepared').value||brand.name||'Your business name',overview:$('#docOverview').value||'',scope:$('#docScope').value||'',timeline:$('#docTimeline').value||'To be agreed',due:$('#docDue').value||'To be agreed',amount:$('#docAmount').value,currency:$('#docCurrency').value,terms:$('#docTerms').value||'Payment schedule to be agreed before work begins.',next:$('#docNext').value||'Reply to confirm the scope and preferred start date.'}}
function updateDocumentPreview(){let d=docData();$('#paperTitle').textContent=d.title;$('#paperClient').textContent=d.client;$('#paperPrepared').textContent=d.prepared;$('#paperOverview').textContent=d.overview||'Add a project overview in the editor.';let scope=d.scope.split('\n').map(s=>s.trim()).filter(Boolean);$('#paperScope').innerHTML='';(scope.length?scope:['Define the work and deliverables','Agree milestones and review points','Deliver final files and handover']).forEach(s=>{let li=document.createElement('li');li.textContent=s;$('#paperScope').appendChild(li)});$('#paperTimeline').textContent=d.timeline;$('#paperDue').textContent=d.due;$('#paperAmount').textContent=d.amount?money(d.amount,d.currency):'To be confirmed';$('#paperTerms').textContent=d.terms;$('#paperNext').textContent=d.next;$('#paperBrandName').textContent=d.prepared;$('#paperContact').textContent=[brand.email,brand.phone].filter(Boolean).join(' · ')||'Your email · Your phone';$('#documentPreview').style.setProperty('--accent',brand.color||selectedColor)}
function documentText(d=docData()){return `${d.title.toUpperCase()}\n\nPrepared for: ${d.client}\nPrepared by: ${d.prepared}\n\nOVERVIEW\n${d.overview}\n\nSCOPE OF WORK\n${d.scope}\n\nTIMELINE: ${d.timeline}\nVALID UNTIL / DUE DATE: ${d.due}\nTOTAL INVESTMENT: ${d.amount?money(d.amount,d.currency):'To be confirmed'}\n\nPAYMENT TERMS\n${d.terms}\n\nNEXT STEPS\n${d.next}\n\n${brand.name||d.prepared}\n${brand.email||''} ${brand.phone||''}\n${brand.website||''}\n\nCreated with TAMPslat — Digital and Ready.`}
function saveDocument(){let d=docData();recent.unshift({title:d.title,kind:d.kind,client:d.client,when:new Date().toLocaleDateString(),text:documentText(d)});recent=recent.slice(0,8);persist();renderRecent();toast('Document saved to recent work.');}
function renderRecent(){let el=$('#recentList');if(!recent.length){el.innerHTML=`<div class="empty-state"><span>✧</span><b>${tr('nothingyet')}</b><p>${tr('nothingdesc')}</p><button class="text-link" data-view="documents">${tr('startcreating')}</button></div>`;el.querySelector('[data-view]')?.addEventListener('click',()=>showView('documents'));return}el.innerHTML=recent.map((r,i)=>`<div class="recent-item" style="display:flex;align-items:center;gap:11px;padding:11px 0;border-bottom:1px solid var(--line)"><span class="card-icon icon-purple" style="width:31px;height:31px;margin:0;font-size:14px">${r.kind==='quotation'?'₦':r.kind==='brief'?'☷':'✎'}</span><div style="min-width:0;flex:1"><b style="display:block;font-size:11px;overflow-wrap:anywhere">${esc(r.title)}</b><small style="color:#9398ab;font-size:9px">${esc(r.client)} · ${esc(r.when)}</small></div><button class="row-delete" data-recent="${i}" title="Download">↓</button></div>`).join('');el.querySelectorAll('[data-recent]').forEach(b=>b.onclick=()=>downloadText(recent[+b.dataset.recent].title+'.txt',recent[+b.dataset.recent].text))}
function updateEstimate(){let h=Math.max(0,+$('#calcHours').value||0),r=Math.max(0,+$('#calcRate').value||0),cost=Math.max(0,+$('#calcCosts').value||0),margin=Math.min(90,Math.max(0,+$('#calcMargin').value||0))/100,c=$('#calcCurrency').value,lab=h*r,base=lab+cost,profit=base*margin,total=base+profit;$('#estimateTotal').textContent=money(total,c);$('#estimateName').textContent=$('#calcProject').value||'Project estimate';$('#labourValue').textContent=money(lab,c);$('#otherValue').textContent=money(cost,c);$('#marginValue').textContent=money(profit,c);$('#currencyPrefix').textContent=currencyMeta[c].symbol;$('#costPrefix').textContent=currencyMeta[c].symbol;return {total,lab,cost,profit,currency:c,name:$('#calcProject').value||'Project estimate'}}
function useEstimate(){let e=updateEstimate();openTool('quotation');$('#docTitle').value='Quotation — '+e.name;$('#docOverview').value='Thank you for the opportunity to provide this quotation. The proposed fees are based on the scope discussed.';$('#docScope').value=`Labour / professional services — ${money(e.lab,e.currency)}\nOther project costs — ${money(e.cost,e.currency)}\nMargin allowance — ${money(e.profit,e.currency)}`;$('#docAmount').value=Math.round(e.total*100)/100;$('#docCurrency').value=e.currency;updateDocumentPreview()}
function persist(){try{localStorage.setItem('tampslat-v1',JSON.stringify({recent,clients,brand,selectedColor}))}catch(e){console.warn('Local save unavailable',e)}}function loadSaved(){try{let s=JSON.parse(localStorage.getItem('tampslat-v1')||'{}');recent=s.recent||[];clients=s.clients||[];brand={...brand,...(s.brand||{})};selectedColor=s.selectedColor||brand.color||'#7258e8'}catch(e){}}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function renderClients(){let query=($('#clientSearch')?.value||'').toLowerCase(),status=$('#clientStatusFilter')?.value||'all';let rows=clients.filter(c=>(status==='all'||c.status===status)&&[c.name,c.project,c.email,c.notes].join(' ').toLowerCase().includes(query));$('#clientsTable').innerHTML=rows.length?rows.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.project||'—')}</td><td><span class="status-badge ${c.status==='Completed'?'completed':c.status==='In progress'?'in-progress':''}">${esc((statusLabels[lang]||statusLabels.en)[c.status]||c.status)}</span></td><td>${esc(c.email||'—')}</td><td><button class="row-delete" data-delete-client="${c.id}" aria-label="Delete ${esc(c.name)}">×</button></td></tr>`).join(''):`<tr><td colspan="5" class="table-empty">${tr('noclients')}</td></tr>`;$('#totalClients').textContent=clients.length;$('#clientCount').textContent=String(clients.length).padStart(2,'0');$('#leadClients').textContent=clients.filter(c=>c.status==='Lead').length;$('#activeClients').textContent=clients.filter(c=>c.status==='In progress').length;$$('[data-delete-client]').forEach(b=>b.onclick=()=>{clients=clients.filter(c=>c.id!==b.dataset.deleteClient);persist();renderClients();toast('Client removed.')})}
function syncBrandPreview(){ $('#brandName').value=brand.name||'';$('#brandOwner').value=brand.owner||'';$('#brandEmail').value=brand.email||'';$('#brandPhone').value=brand.phone||'';$('#brandWebsite').value=brand.website||'';$('#brandCurrency').value=brand.currency||'NGN';$('#previewBusiness').textContent=brand.name||'Your Business';$('#previewOwner').textContent=brand.owner||'Your name';$('#previewEmail').textContent=brand.email||'hello@yourbusiness.com';$('#brandPreview').style.setProperty('--brand-accent',brand.color||selectedColor);$('#documentPreview')?.style.setProperty('--accent',brand.color||selectedColor);$('#brandCurrency').value=brand.currency||'NGN';$$('.color-picker button').forEach(b=>b.classList.toggle('selected',b.dataset.color===(brand.color||selectedColor)))}
function downloadText(filename,text){let blob=new Blob([text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename.replace(/[\\/:*?"<>|]/g,'-');document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),500);toast('Download prepared.')}
function exportCSV(){let headers=['Name','Email','Project / service','Status','Notes','Added'];let data=clients.map(c=>[c.name,c.email,c.project,c.status,c.notes,c.added]);let csv=[headers,...data].map(row=>row.map(v=>'"'+String(v||'').replace(/"/g,'""')+'"').join(',')).join('\r\n');downloadText('tampslat-client-tracker.csv','\ufeff'+csv)}
