$$('[data-view]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));$$('[data-open-tool]').forEach(b=>b.addEventListener('click',()=>openTool(b.dataset.openTool)));$$('[data-tool]').forEach(b=>b.addEventListener('click',()=>openTool(b.dataset.tool)));$('#browseTemplates').onclick=()=>showView('documents');$('#language').addEventListener('change',e=>{lang=e.target.value;applyLanguage();if($('#publicLanguage'))$('#publicLanguage').value=lang;window.dispatchEvent(new CustomEvent('tampslat-language-change',{detail:{lang}}));toast(lang==='ar'?'تم تغيير اللغة':lang==='fr'?'Langue modifiée':lang==='pt'?'Idioma alterado':lang==='es'?'Idioma cambiado':'Language changed')});function setTheme(theme){document.body.classList.toggle('dark',theme==='dark');try{localStorage.setItem('tampslat-theme',theme)}catch{};const t=$('#profileThemeToggle');if(t){t.textContent=theme==='dark'?'☀️ Light theme':'🌙 Dark theme';t.setAttribute('aria-pressed',String(theme==='dark'))}const main=$('#themeToggle');if(main)main.textContent=theme==='dark'?'☀':'◐'};setTheme((()=>{try{return localStorage.getItem('tampslat-theme')||'light'}catch{return 'light'}})());$('#themeToggle').onclick=()=>setTheme(document.body.classList.contains('dark')?'light':'dark');$('#mobileMenu').onclick=()=>$('.sidebar').classList.toggle('mobile-open');
