const profileToggle=$('#profileMenuToggle'), profileMenu=$('#profileMenu');
if(profileToggle&&profileMenu){profileToggle.addEventListener('click',()=>{const open=profileMenu.hidden;profileMenu.hidden=!open;profileToggle.setAttribute('aria-expanded',String(open));});document.addEventListener('click',e=>{if(!e.target.closest('.profile-menu-wrap')){profileMenu.hidden=true;profileToggle.setAttribute('aria-expanded','false')}})}
