// Native drag-and-drop: users can reorder the four dashboard shortcuts. Order is saved locally.
function enableToolReorder(){const grid=$('.tool-grid');if(!grid)return;let dragged=null;[...grid.children].forEach((card,i)=>{card.dataset.toolKey=card.dataset.openTool||`tool-${i}`});try{const order=JSON.parse(localStorage.getItem('tampslat-tool-order')||'[]');order.forEach(key=>{const card=[...grid.children].find(c=>c.dataset.toolKey===key);if(card)grid.appendChild(card)})}catch{};[...grid.children].forEach(card=>{card.draggable=true;card.addEventListener('dragstart',e=>{dragged=card;card.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',card.dataset.toolKey)});card.addEventListener('dragend',()=>{card.classList.remove('dragging');[...grid.children].forEach(c=>c.classList.remove('drag-over'));localStorage.setItem('tampslat-tool-order',JSON.stringify([...grid.children].map(c=>c.dataset.toolKey)));dragged=null});card.addEventListener('dragover',e=>{e.preventDefault();if(dragged&&dragged!==card){card.classList.add('drag-over');e.dataTransfer.dropEffect='move'}});card.addEventListener('dragleave',()=>card.classList.remove('drag-over'));card.addEventListener('drop',e=>{e.preventDefault();card.classList.remove('drag-over');if(dragged&&dragged!==card){const r=card.getBoundingClientRect(),after=(e.clientY-r.top)/r.height>.5;grid.insertBefore(dragged,after?card.nextSibling:card);localStorage.setItem('tampslat-tool-order',JSON.stringify([...grid.children].map(c=>c.dataset.toolKey)))}})})}
enableToolReorder();
