// Local AI-assistance preview: shows contextual guidance without pretending a provider is connected.
const aiGuidance={document:'Start with the audience, purpose, key details, tone, deliverables and next action. Review names, figures, dates and commercial terms before sharing the draft.',pdf:'Summarise the document by extracting its purpose, key points, dates, obligations, risks and open questions. Verify every quotation against the original PDF.',spreadsheet:'Check column headers, blank cells, duplicate rows, inconsistent date formats, outliers and totals. Preserve an original copy before applying bulk cleaning.',ocr:'After OCR, verify names, totals, dates and low-confidence text against the source image. Avoid treating OCR output as authoritative without checking.',zip:'List the archive contents first, identify file types and duplicates, then extract only what is needed. Do not open files from untrusted archives.',batch:'Define the desired outcome, map each file type to a supported operation, preview the actions, then process and review the results before exporting.'};
async function runAiPreview(task){const input=document.getElementById('aiPrompt'),out=document.getElementById('aiAssistOutput'),button=document.getElementById('aiAssistButton');if(!input||!out)return;const prompt=input.value.trim();if(!prompt){out.textContent='Describe the task you want help with, then generate guidance.';return;}if(window.TAMPSLAT_API){out.textContent='Connecting securely to TAMPslat AI…';if(button)button.disabled=true;try{const result=await window.TAMPSLAT_API.generate(task||'document',prompt);out.textContent=result.output+'\n\nCredits remaining: '+result.creditsRemaining;return;}catch(err){if(err.status===401){out.textContent='Sign in to use live AI. Your prompt has not been sent. Open Sign in to continue.';return;}if(err.status===402){out.textContent=err.message+' No AI output was generated.';return;}if(err.status!==404&&err.status!==503){out.textContent=err.message;return;}}finally{if(button)button.disabled=false;}}out.textContent=(prompt?'For your request (“'+prompt.slice(0,180)+'”), ':'')+aiGuidance[task||'document']+'\n\nLocal preview only. Deploy the TAMPslat Worker and configure the AI provider to enable live responses.';}
document.querySelectorAll('[data-ai-task]').forEach(b=>b.addEventListener('click',()=>{const task=b.dataset.aiTask;const prompts={document:'Help me draft a professional business document.',pdf:'Help me understand and summarise a PDF.',spreadsheet:'Help me inspect and clean a spreadsheet.',batch:'Help me plan a safe batch workflow.'};const input=document.getElementById('aiPrompt');if(input)input.value=prompts[task]||'';runAiPreview(task)}));document.getElementById('aiAssistButton')?.addEventListener('click',()=>runAiPreview('document'));

window.addEventListener('tampslat-language-change',e=>{lang=e.detail.lang;applyLanguage();if($('#language'))$('#language').value=lang});window.addEventListener('storage',e=>{if(e.key==='tampslat-language'){lang=e.newValue||'en';applyLanguage();if($('#language'))$('#language').value=lang;if($('#publicLanguage'))$('#publicLanguage').value=lang}if(e.key==='tampslat-theme')setTheme(e.newValue||'light')});

