function translateProfileMenu(){const m=$('#profileMenu');if(!m)return;const links=m.querySelectorAll('a');if(links[0])links[0].textContent=translations[lang].profile;if(links[1])links[1].textContent=translations[lang].homepage;if(links[2])links[2].textContent=translations[lang].settings;if(links[3])links[3].textContent=translations[lang].support;const b=$('#profileThemeToggle');if(b)b.textContent=document.body.classList.contains('dark')?translations[lang].lighttheme:translations[lang].darktheme;}
const priorApplyLanguage=applyLanguage;applyLanguage=function(){priorApplyLanguage();translateProfileMenu();if($('#publicLanguage'))$('#publicLanguage').value=lang};
const priorSetTheme=setTheme;setTheme=function(theme){priorSetTheme(theme);if(typeof translateProfileMenu==='function')translateProfileMenu()};applyLanguage();
